function calculatorExample(){const {p,form}=formProject('Calculator','frmCalculator','Calculator',292,302);form.form.controls=[c('TextBox','txtDisplay',14,14,264,40,{Text:'0',Alignment:1,FontSize:20,BackColor:16777215,Locked:-1})];for(let digit=0;digit<=9;digit++){const pos=digit===0?[0,3]:[(digit-1)%3,2-Math.floor((digit-1)/3)];form.form.controls.push(c('CommandButton','cmdDigit',14+pos[0]*66,68+pos[1]*48,58,40,{Caption:String(digit),FontSize:13,Index:digit}));}for(const [index,caption]of ['+','−','×','÷'].entries())form.form.controls.push(c('CommandButton','cmdOperator',212,68+index*48,66,40,{Caption:caption,FontSize:13,Index:index}));form.form.controls.push(c('CommandButton','cmdDecimal',80,212,58,40,{Caption:'.',FontSize:13}),c('CommandButton','cmdEquals',146,212,58,40,{Caption:'=',FontSize:13,Default:-1}),c('CommandButton','cmdClear',14,265,264,25,{Caption:'Clear',Cancel:-1}));form.code=`Option Explicit
Private firstNumber As Double
Private operation As Integer
Private newNumber As Boolean

Private Sub Form_Load()
    newNumber = True
    operation = -1
End Sub

Private Sub cmdDigit_Click(Index As Integer)
    If newNumber Or txtDisplay.Text = "0" Then
        txtDisplay.Text = CStr(Index)
        newNumber = False
    Else
        txtDisplay.Text = txtDisplay.Text & CStr(Index)
    End If
End Sub

Private Sub cmdDecimal_Click()
    If newNumber Then txtDisplay.Text = "0"
    If InStr(txtDisplay.Text, ".") = 0 Then txtDisplay.Text = txtDisplay.Text & "."
    newNumber = False
End Sub

Private Sub cmdOperator_Click(Index As Integer)
    firstNumber = Val(txtDisplay.Text)
    operation = Index
    newNumber = True
End Sub

Private Sub cmdEquals_Click()
    On Error GoTo CalculateError
    Dim secondNumber As Double
    Dim result As Double
    secondNumber = Val(txtDisplay.Text)
    Select Case operation
        Case 0
            result = firstNumber + secondNumber
        Case 1
            result = firstNumber - secondNumber
        Case 2
            result = firstNumber * secondNumber
        Case 3
            result = firstNumber / secondNumber
        Case Else
            result = secondNumber
    End Select
    txtDisplay.Text = CStr(result)
    newNumber = True
    Exit Sub
CalculateError:
    MsgBox Err.Description, vbExclamation, "Calculator"
    newNumber = True
End Sub

Private Sub cmdClear_Click()
    txtDisplay.Text = "0"
    firstNumber = 0
    operation = -1
    newNumber = True
End Sub
`;return p;}
